314	    ///
315	    /// ## Panics
316	    /// This function may panic if the internal settings mutex has been poisoned
317	    /// by another thread having previously panicked while holding the lock
318	    #[tracing::instrument(level = "debug", skip(self))]
319	    fn update_settings(&self, params: UpdateSettingsParams) -> Result<(), WorkspaceError> {
320	        let mut settings = self.settings.write().unwrap();
321	
322	        settings.merge_with_configuration(
323	            params.configuration,
324	            params.working_directory,
325	            params.vcs_base_path,
326	            params.gitignore_matches.as_slice(),
327	        )?;
328	
329	        // settings changed, hence everything that is computed from the settings needs to be purged
330	        self.file_features.clear();
331	        Ok(())
332	    }
