464	fn to_file_settings(
465	    working_directory: Option<PathBuf>,
466	    config: Option<FilesConfiguration>,
467	    vcs_config_path: Option<PathBuf>,
468	    gitignore_matches: &[String],
469	) -> Result<Option<FilesSettings>, WorkspaceError> {
470	    let config = if let Some(config) = config {
471	        Some(config)
472	    } else if vcs_config_path.is_some() {
473	        Some(FilesConfiguration::default())
474	    } else {
475	        None
476	    };
477	
478	    Ok(if let Some(config) = config {
479	        Some(FilesSettings {
480	            max_size: config.max_size.unwrap_or(DEFAULT_FILE_SIZE_LIMIT),
481	            ignored_files: to_matcher(
482	                working_directory.clone(),
483	                config.ignore.as_ref(),
484	                vcs_config_path.clone(),
485	                gitignore_matches,
486	            )?,
487	            // Don't set `gitignore` for the include matcher.
488	            // TODO: it could better to create dedicated matcher types:
489	            // one for ignore and the other for include.
490	            included_files: to_matcher(working_directory, config.include.as_ref(), None, &[])?,
491	            ignore_unknown: config.ignore_unknown.unwrap_or_default(),
492	        })
493	    } else {
494	        None
495	    })
496	}
